tasks.setup:
CREATE TABLE events(
  id bigserial PRIMARY KEY,
  org_id int NOT NULL,
  created_at int NOT NULL,
  kind text NOT NULL CHECK (kind IN ('click','view','buy'))
);
INSERT INTO events(org_id, created_at, kind)
SELECT (g % 10) + 1, g, (ARRAY['click','view','buy'])[(g % 3) + 1]
FROM generate_series(1, 1000) g;
CREATE INDEX events_org_recent ON events(org_id, created_at DESC);
SELECT org_id, created_at, kind
FROM events
WHERE org_id = 7
ORDER BY created_at DESC
LIMIT 3;

